'employee_terminations'=>"CREATE TABLE IF NOT EXISTS employee_terminations(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pharmacy_id INT UNSIGNED NOT NULL,staff_id INT UNSIGNED NOT NULL,termination_date DATE NOT NULL,termination_type VARCHAR(120) NOT NULL,reason TEXT NOT NULL,status ENUM('Proposed','Approved','Completed','Cancelled') NOT NULL DEFAULT 'Proposed',approved_by INT UNSIGNED NULL,approved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY(pharmacy_id),KEY(staff_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
'employee_holidays'=>"CREATE TABLE IF NOT EXISTS employee_holidays(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pharmacy_id INT UNSIGNED NOT NULL,holiday_date DATE NOT NULL,holiday_name VARCHAR(180) NOT NULL,description TEXT,is_paid TINYINT(1) NOT NULL DEFAULT 1,created_by INT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY(pharmacy_id,holiday_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];
foreach($ddl as $sql)if(!$conn->query($sql)){http_response_code(500);exit('Employee HR table setup failed: '.h($conn->error));}

if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();$a=$_POST['action']??'';$tab=$_POST['tab']??'overview';
 if($a==='leave_add'){$sid=(int)$_POST['staff_id'];$type=trim($_POST['leave_type']??'Annual');$st=$_POST['start_date']??'';$en=$_POST['end_date']??'';$reason=trim($_POST['reason']??'');$days=days_inc($st,$en);if(!emp_ok($sid)||!$st||!$en||$days<=0)back('leave','', 'Invalid employee or dates.');$s=$conn->prepare('INSERT INTO employee_leave_requests(pharmacy_id,staff_id,leave_type,start_date,end_date,days,reason) VALUES(?,?,?,?,?,?,?)');$s->bind_param('iisssds',$pharmacy_id,$sid,$type,$st,$en,$days,$reason);$s->execute();$s->close();back('leave','Leave request recorded.');}
