 if($a==='transfer_add'){$sid=(int)$_POST['staff_id'];$to=(int)$_POST['to_branch_id'];$date=$_POST['effective_date']??'';$reason=trim($_POST['reason']??'');if(!emp_ok($sid)||!branch_ok($to)||!$date)back('transfers','', 'Invalid employee, branch or date.');$s=$conn->prepare('SELECT branch_id FROM users WHERE id=? AND pharmacy_id=? LIMIT 1');$s->bind_param('ii',$sid,$pharmacy_id);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();$from=(int)($r['branch_id']??0);$s=$conn->prepare('INSERT INTO employee_transfers(pharmacy_id,staff_id,from_branch_id,to_branch_id,effective_date,reason,created_by) VALUES(?,?,?,?,?,?,?)');$s->bind_param('iiiissi',$pharmacy_id,$sid,$from,$to,$date,$reason,$user_id);$s->execute();$s->close();back('transfers','Transfer submitted.');}
 if($a==='transfer_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'';if(!in_array($status,['Approved','Rejected','Completed'],true))back('transfers','', 'Invalid status.');$s=$conn->prepare('SELECT staff_id,to_branch_id FROM employee_transfers WHERE id=? AND pharmacy_id=? LIMIT 1');$s->bind_param('ii',$id,$pharmacy_id);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();if(!$r)back('transfers','', 'Transfer not found.');if($status==='Completed'){$conn->begin_transaction();try{$u=$conn->prepare('UPDATE users SET branch_id=? WHERE id=? AND pharmacy_id=?');$u->bind_param('iii',$r['to_branch_id'],$r['staff_id'],$pharmacy_id);$u->execute();$u->close();$u=$conn->prepare("UPDATE employee_transfers SET status='Completed',approved_by=? WHERE id=? AND pharmacy_id=?");$u->bind_param('iii',$user_id,$id,$pharmacy_id);$u->execute();$u->close();$conn->commit();}catch(Throwable $e){$conn->rollback();back('transfers','', 'Transfer could not be completed.');}}else{$u=$conn->prepare('UPDATE employee_transfers SET status=?,approved_by=? WHERE id=? AND pharmacy_id=?');$u->bind_param('siii',$status,$user_id,$id,$pharmacy_id);$u->execute();$u->close();}back('transfers','Transfer updated.');}
 if($a==='award_add'){$sid=(int)$_POST['staff_id'];$title=trim($_POST['award_title']??'');$date=$_POST['award_date']??'';$desc=trim($_POST['description']??'');$amt=(float)($_POST['amount']??0);if(!emp_ok($sid)||!$title||!$date)back('awards','', 'Employee, title and date are required.');$s=$conn->prepare('INSERT INTO employee_awards(pharmacy_id,staff_id,award_title,award_date,description,amount,created_by) VALUES(?,?,?,?,?,?,?)');$s->bind_param('iisssdi',$pharmacy_id,$sid,$title,$date,$desc,$amt,$user_id);$s->execute();$s->close();back('awards','Award recorded.');}
