 if($a==='resignation_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'';if(!in_array($status,['Accepted','Withdrawn'],true))back('resignations','', 'Invalid status.');$s=$conn->prepare('UPDATE employee_resignations SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND pharmacy_id=?');$s->bind_param('siii',$status,$user_id,$id,$pharmacy_id);$s->execute();$s->close();back('resignations','Resignation updated.');}
