 if($a==='complaint_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'';$res=trim($_POST['resolution']??'');if(!in_array($status,['Open','Under Review','Resolved','Closed'],true))back('complaints','', 'Invalid status.');$s=$conn->prepare('UPDATE employee_complaints SET status=?,resolution=?,handled_by=?,handled_at=NOW() WHERE id=? AND pharmacy_id=?');$s->bind_param('ssiii',$status,$res,$user_id,$id,$pharmacy_id);$s->execute();$s->close();back('complaints','Complaint updated.');}
